pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient, uint256 amount) public {
        // recipient cannot be the owner, because the bug sends to the owner and would succeed there
        vm.assume(recipient != address(this));
        // recipient cannot be a precompile or the contract itself
        vm.assume(recipient != address(c));
        vm.assume(recipient != address(1));
        vm.assume(recipient != address(2));
        vm.assume(recipient != address(3));
        vm.assume(recipient != address(4));
        vm.assume(recipient != address(5));
        vm.assume(recipient != address(6));
        vm.assume(recipient != address(7));
        vm.assume(recipient != address(8));
        vm.assume(recipient != address(9));
        // Fund the contract
        vm.deal(address(c), amount);
        // Deploy an adversarial recipient that reverts on receive
        Reverter reverter = new Reverter();
        // We want to test: if c.withdrawAll is called with a recipient that reverts on receive,
        // the reference (which sends to the supplied recipient) will revert (balance stays >0),
        // but the buggy version sends to the owner (which accepts) and succeeds (balance goes to 0).
        // This matches the rule: after a successful withdrawAll, contract balance MUST be 0.
        // We need the owner to call withdrawAll with the adversarial recipient.
        // The reference call to withdrawAll(adversarial) reverts, so no state change.
        // The buggy call withdrawAll(adversarial) sends to owner instead, succeeds, balance becomes 0.
        // Therefore, the property "after the call, balance is not 0" holds for the reference (it reverts),
        // but breaks for the buggy version (it succeeds and drains balance).
        bool success;
        try c.withdrawAll(address(reverter)) {
            success = true;
        } catch {
            success = false;
        }
        // Reference: call reverts -> success == false -> balance stays amount -> amount > 0
        // Buggy: call succeeds -> success == true -> balance becomes 0
        // Property: if success is false, balance must be > 0 (reference holds)
        // Bug breaks: success becomes true, balance is 0, so the condition if(!success) balance > 0 is not violated,
        // but actually we want a property that is true for reference, false for bug.
        // Let's assert: after the call, if it reverted, balance > 0 (always true for reference because it always reverts with adversarial).
        // But the bug never reverts, so the antecedent is false, making the implication true for bug as well.
        // Better: assert that success == false. Because reference always fails (adversarial recipient reverts).
        // Bug always succeeds (sends to owner). So assertTrue(!success) is true for reference, false for bug.
        // However, we must ensure that reference indeed always fails. The recipient is a contract with fallback that reverts.
        // The call to transfer in reference sends to that contract, which reverts, so withdrawAll always reverts.
        // The buggy sends to owner, which is an EOA, always succeeds. So success is false for reference, true for bug.
        assertTrue(!success);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

