// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient, uint256 initialBalance) public {
        vm.assume(recipient != address(c));
        vm.assume(recipient != address(0));
        initialBalance = bound(initialBalance, 1, 100 ether);

        vm.deal(address(c), initialBalance);
        uint256 recipientBefore = recipient.balance;

        vm.prank(address(this));
        c.withdrawAll(recipient);

        uint256 recipientAfter = recipient.balance;
        uint256 delta = recipientAfter - recipientBefore;
        assertTrue(delta == initialBalance);
    }
}
